import axios from 'axios';

// API base URL 讀取 .env，如果沒設定就預設 /api
const API_BASE_URL = process.env.REACT_APP_API_URL || '/api';


export const getHealthStatus = () => {
  return axios.get(`${API_BASE_URL}/api/health`);
};

// 創建 axios 實例
const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// 請求攔截器
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// 響應攔截器
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// 測試 API 連線
export const testApiConnection = async () => {
  try {
    console.log('目前 API base URL:', API_BASE_URL);
    const response = await api.get('/health');
    console.log('✅ API 成功回傳:', response.data);
    return response.data;
  } catch (error) {
    console.error('❌ API 連線失敗:', error);
    throw error;
  }
};

// 認證相關 API
export const authAPI = {
  login: (email: string, password: string) =>
    api.post('/auth/login', { email, password }),
  getProfile: () => api.get('/auth/profile'),
};

// 參與者相關 API
export const participantAPI = {
  // 取得所有參與者
  getAll: () => api.get('/participants'),

  // 取得單一參與者
  getById: (id: number) => api.get(`/participants/${id}`),

  // 新增參與者
  create: (data: {
    uuid?: string;
    projectId: string;
    subProjectId: string;
    name: string;
    phone?: string;
    email?: string;
    address?: string;
    birthDate?: string;
    gender?: string;
  }) => api.post('/participants', data),

  // 更新參與者基本資料
  update: (id: number, data: {
    name: string;
    phone?: string;
    email?: string;
    address?: string;
    birthDate?: string;
    gender?: string;
  }) => api.put(`/participants/${id}`, data),

  // 刪除參與者
  delete: (id: number) => api.delete(`/participants/${id}`),

  // 更新參與者的計畫狀態
  updateProjectStatus: (
    participantId: number, 
    projectKey: string, 
    data: {
      status: string;
      participantProjectId?: string;
      participantSubProjectId?: string;
      terminationReason?: string;
      consentVersions?: string[];
      joinDate?: string;
    }
  ) => api.put(`/participants/${participantId}/projects/${projectKey}`, data),

  // 新增參與者到計畫
  addToProject: (participantId: number, data: {
    projectId: string;
    subProjectId: string;
    participantProjectId?: string;
    participantSubProjectId?: string;
    status?: string;
    terminationReason?: string;
    consentVersions?: string[];
    joinDate?: string;
  }) => api.post(`/participants/${participantId}/projects`, data),
};

// 計畫相關 API
export const projectAPI = {
  // 取得所有計畫
  getAll: () => api.get('/projects'),

  // 取得單一計畫
  getById: (id: number) => api.get(`/projects/${id}`),

  // 新增計畫
  create: (data: {
    projectId: string;
    subProjectId: string;
    projectName: string;
    researcherName: string;
    researcherEmail?: string;
    description?: string;
  }) => api.post('/projects', data),

  // 更新計畫描述
  updateDescription: (id: number, description: string) => 
    api.put(`/projects/${id}`, { description }),

  // 取得計畫統計資料
  getStats: (projectId: string, subProjectId: string) =>
    api.get(`/projects/${projectId}/${subProjectId}/stats`),

  // 取得計畫的參與者
  getParticipants: (projectId: string, subProjectId: string) =>
    api.get(`/projects/${projectId}/${subProjectId}/participants`),
};

export default api;
